using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static partial class StackHouse3DSigns{
public static Mesh BuildParkingPlaza(int style,bool detailed,Material material){atlas=new Texture2D(2,2);atlas.LoadImage(File.ReadAllBytes(AssetDatabase.GetAssetPath(material.GetTexture("_BaseMap"))));var gold=ColorUV(new Color(1,.74f,.035f));var white=ColorUV(new Color(.96f,.97f,1));var dark=ColorUV(new Color(.025f,.035f,.06f));var blue=ColorUV(new Color(.025f,.19f,.85f));var green=ColorUV(new Color(.05f,.55f,.08f));var red=ColorUV(new Color(.8f,.015f,.025f));var words=JsonUtility.FromJson<LetterContours>(File.ReadAllText("Assets/Scenes/Oasis/ParkingPlazaUpgrade/Parking Letter Contours.json")).words;var g=new G();Action<string,float,float,float,float,Vector2> text=(name,cx,cy,w,h,color)=>{var word=words.Single(a=>a.text==name);var pts=word.loops.SelectMany(a=>a.points).ToArray();float xmin=pts.Min(a=>a.x),xmax=pts.Max(a=>a.x),ymin=pts.Min(a=>a.y),ymax=pts.Max(a=>a.y);var loops=word.loops.Select(a=>a.points.Select(p=>new Vector2(cx-((p.x-xmin)/(xmax-xmin)-.5f)*w,cy+(.5f-(p.y-ymin)/(ymax-ymin))*h)).ToArray()).ToList();surfaceType=1;FillContours(g,loops,.61f,color,.65f);foreach(var loop in loops)for(int i=0;i<loop.Length;i++){var a=loop[i];var b=loop[(i+1)%loop.Length];g.Quad(new Vector3(a.x,a.y,.61f),new Vector3(a.x,a.y,.21f),new Vector3(b.x,b.y,.21f),new Vector3(b.x,b.y,.61f),dark,dark,dark,dark);}};
if(style==0){surfaceType=0;g.Box(Vector3.zero,new Vector3(31,4.7f,.65f),dark);Tube(g,RoundRect(30.7f,4.4f,0,.37f,.5f,detailed?8:3),.075f,gold,3.2f,detailed?6:4);g.Box(new Vector3(12.4f,0,.38f),new Vector3(3.6f,3.6f,.18f),blue,.5f);Tube(g,RoundRect(3.4f,3.4f,0,.51f,.35f,detailed?6:3).Select(v=>v+Vector3.right*12.4f).ToList(),.065f,white,2.2f,5);text("P",12.4f,0,2.25f,2.8f,white);text("PARKING",3.1f,0,13f,2.65f,white);text("PLAZA",-9.2f,0,7.7f,2.65f,gold);
var car=new List<Vector3>{new Vector3(-7,2.55f,.1f),new Vector3(-6.2f,3.05f,.1f),new Vector3(-3.3f,3.45f,.1f),new Vector3(-1.4f,4.65f,.1f),new Vector3(1.7f,4.8f,.1f),new Vector3(4.4f,3.5f,.1f),new Vector3(6.6f,3.3f,.1f),new Vector3(7.4f,2.55f,.1f)};var smoothCar=new List<Vector3>();for(int ci=0;ci<car.Count-1;ci++){var p0=car[Mathf.Max(0,ci-1)];var p1=car[ci];var p2=car[ci+1];var p3=car[Mathf.Min(car.Count-1,ci+2)];for(int j=0;j<5;j++){float t=j/5f;smoothCar.Add(.5f*((2*p1)+(-p0+p2)*t+(2*p0-5*p1+4*p2-p3)*t*t+(-p0+3*p1-3*p2+p3)*t*t*t));}}smoothCar.Add(car[car.Count-1]);car=smoothCar;surfaceType=1;Tube(g,car,.17f,dark,0,6);surfaceType=0;Tube(g,car.Select(v=>v+Vector3.forward*.18f).ToList(),.085f,gold,4,6);Tube(g,new List<Vector3>{new Vector3(-7,2.55f,.28f),new Vector3(7.4f,2.55f,.28f)},.065f,gold,3,5);Tube(g,new List<Vector3>{new Vector3(-3.3f,3.45f,.28f),new Vector3(4.4f,3.5f,.28f)},.065f,gold,3,5);Tube(g,new List<Vector3>{new Vector3(.5f,3.5f,.28f),new Vector3(1.7f,4.8f,.28f)},.065f,gold,3,5);for(int i=-1;i<=1;i+=2)g.Box(new Vector3(i*9,-3.1f,-.15f),new Vector3(.25f,1.5f,.25f),dark);}
else if(style==1){surfaceType=0;var circle=Enumerable.Range(0,detailed?49:25).Select(i=>{float a=i*Mathf.PI*2/(detailed?48:24);return new Vector3(Mathf.Cos(a)*2.65f,Mathf.Sin(a)*2.65f,.35f);}).ToList();for(int i=1;i<circle.Count;i++)g.Tri(new Vector3(0,0,.26f),circle[i-1],circle[i],blue,blue,blue,.55f);Tube(g,circle,.095f,white,3,6);text("P",0,0,2.9f,3.6f,white);}
else if(style<6){int floor=style-2;surfaceType=0;g.Box(Vector3.zero,new Vector3(2.2f,2.5f,.4f),gold,.15f);text("P"+floor,0,0,1.75f,1.45f,dark);}
else{bool entry=style==6;surfaceType=0;g.Box(Vector3.zero,new Vector3(5.6f,1.25f,.4f),entry?green:red,.3f);text(entry?"ENTRY":"EXIT",0,0,4.6f,.8f,white);}
var mesh=new Mesh{name="Parking plaza raised sign style "+style};WriteG(mesh,g);UnityEngine.Object.DestroyImmediate(atlas);return mesh;}
public static Mesh BuildParkingLightTrim(List<Vector3[]> paths,Material material){atlas=new Texture2D(2,2);atlas.LoadImage(File.ReadAllBytes(AssetDatabase.GetAssetPath(material.GetTexture("_BaseMap"))));var warm=ColorUV(new Color(1,.63f,.08f));var g=new G();surfaceType=0;foreach(var path in paths)Tube(g,path.ToList(),.08f,warm,3,5);var mesh=new Mesh{name="Parking plaza warm roof and soffit accents"};WriteG(mesh,g);UnityEngine.Object.DestroyImmediate(atlas);return mesh;}
}
